/* ---------- Procedural Gravel ---------------------------------------------
   No bundled gravel PNG exists yet — until you drop one in, build a passable
   16×16 gravel texture in-memory: warm gray base with a deterministic spray
   of darker pebbles. The hash is index-driven so the output is identical
   across reloads. Replace by dropping `gravel.png`'s base64 above and
   removing this block. */
(function generateProceduralGravel(){
  if (window.MC_TEX.gravel) return;
  const N = 16;
  const c = document.createElement('canvas');
  c.width = c.height = N;
  const g = c.getContext('2d');
  const img = g.createImageData(N, N);
  const hash = (x, y) => {
    let h = (x * 374761393 + y * 668265263) | 0;
    h = ((h ^ (h >>> 13)) * 1274126177) | 0;
    return ((h ^ (h >>> 16)) >>> 0) / 0x100000000;
  };
  for (let y = 0; y < N; y++){
    for (let x = 0; x < N; x++){
      const r = hash(x, y);
      let v;
      if (r < 0.20)      v = 92  + Math.floor(hash(x+1, y+7) * 14);
      else if (r < 0.78) v = 145 + Math.floor(hash(x+3, y+5) * 22);
      else               v = 175 + Math.floor(hash(x+9, y+2) * 22);
      const i = (y * N + x) * 4;
      img.data[i]     = v;
      img.data[i + 1] = v;
      img.data[i + 2] = Math.max(80, v - 8);
      img.data[i + 3] = 255;
    }
  }
  g.putImageData(img, 0, 0);
  window.MC_TEX.gravel = c.toDataURL('image/png');
})();
